ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN ('user','admin'));
CREATE TABLE IF NOT EXISTS vehicle_brands(id SERIAL PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name))>0),active BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS vehicle_brands_name ON vehicle_brands(lower(name));
CREATE TABLE IF NOT EXISTS vehicle_types(id SERIAL PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name))>0),active BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS vehicle_types_name ON vehicle_types(lower(name));
CREATE TABLE IF NOT EXISTS vehicle_models(id SERIAL PRIMARY KEY,brand_id INT NOT NULL REFERENCES vehicle_brands(id),type_id INT REFERENCES vehicle_types(id),name TEXT NOT NULL CHECK(length(trim(name))>0),active BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS vehicle_models_name ON vehicle_models(brand_id,lower(name));
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS brand_id INT REFERENCES vehicle_brands(id);
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS model_id INT REFERENCES vehicle_models(id);
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS type_id INT REFERENCES vehicle_types(id);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='models_id_brand_unique') THEN ALTER TABLE vehicle_models ADD CONSTRAINT models_id_brand_unique UNIQUE(id,brand_id);END IF;IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='vehicles_model_brand_fk') THEN ALTER TABLE vehicles ADD CONSTRAINT vehicles_model_brand_fk FOREIGN KEY(model_id,brand_id) REFERENCES vehicle_models(id,brand_id);ALTER TABLE vehicles ADD CONSTRAINT vehicles_model_needs_brand CHECK(model_id IS NULL OR brand_id IS NOT NULL);END IF;END $$;
CREATE INDEX IF NOT EXISTS vehicles_brand_id ON vehicles(brand_id);
CREATE INDEX IF NOT EXISTS vehicles_model_id ON vehicles(model_id);
CREATE INDEX IF NOT EXISTS vehicles_type_id ON vehicles(type_id);
CREATE TABLE IF NOT EXISTS admin_audit_logs(id BIGSERIAL PRIMARY KEY,actor_id INT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity TEXT NOT NULL,target_id INT,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS admin_audit_created ON admin_audit_logs(created_at DESC,id DESC);
CREATE OR REPLACE FUNCTION personal_defaults() RETURNS trigger AS $$ BEGIN IF NEW.role='user' THEN INSERT INTO categories(owner_id,name) VALUES(NEW.id,'Thay dầu động cơ'),(NEW.id,'Thay lọc gió'),(NEW.id,'Kiểm tra phanh'),(NEW.id,'Kiểm tra lốp');INSERT INTO settings(owner_id) VALUES(NEW.id);END IF;RETURN NEW;END $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION admin_change() RETURNS trigger AS $$ BEGIN PERFORM pg_notify('autocare_changes',json_build_object('users',ARRAY[]::int[],'roles',ARRAY['admin'],'resources',CASE WHEN TG_TABLE_NAME='users' THEN ARRAY['admin-users','admin-dashboard'] WHEN TG_TABLE_NAME='vehicles' THEN ARRAY['admin-vehicles','admin-dashboard'] ELSE ARRAY['catalog','admin-dashboard'] END)::text);RETURN NULL;END $$ LANGUAGE plpgsql;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['users','vehicles','vehicle_brands','vehicle_models','vehicle_types'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS admin_change ON %I',t);EXECUTE format('CREATE TRIGGER admin_change AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION admin_change()',t);END LOOP;END $$;
CREATE OR REPLACE FUNCTION catalog_change() RETURNS trigger AS $$ BEGIN PERFORM pg_notify('autocare_changes',json_build_object('users',ARRAY[]::int[],'roles',ARRAY['user'],'resources',ARRAY['catalog'])::text);RETURN NULL;END $$ LANGUAGE plpgsql;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['vehicle_brands','vehicle_models','vehicle_types'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS catalog_change ON %I',t);EXECUTE format('CREATE TRIGGER catalog_change AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION catalog_change()',t);END LOOP;END $$;
INSERT INTO vehicle_brands(name) VALUES('Toyota'),('Honda'),('Hyundai'),('Ford'),('Mazda'),('Kia'),('VinFast') ON CONFLICT DO NOTHING;
INSERT INTO vehicle_types(name) VALUES('Sedan'),('SUV'),('Hatchback'),('Bán tải'),('MPV') ON CONFLICT DO NOTHING;
INSERT INTO vehicle_models(brand_id,type_id,name) SELECT b.id,t.id,x.model FROM (VALUES('Toyota','Sedan','Vios'),('Honda','Sedan','City'),('Hyundai','Sedan','Accent'),('Ford','Bán tải','Ranger')) x(brand,kind,model) JOIN vehicle_brands b ON b.name=x.brand JOIN vehicle_types t ON t.name=x.kind ON CONFLICT DO NOTHING;
